(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.008+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.009-t*0.12)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.4)*110, 70+Math.cos(t*0.3)*50, 0.07, 2.2, 1.0],
    [360+Math.cos(t*0.35)*100, 170+Math.sin(t*0.45)*60, 0.085, 1.9, 0.9],
    [240+Math.sin(t*0.25+2)*150, 100+Math.cos(t*0.4+1)*100, 0.055, 2.6, 1.1],
    [80+Math.cos(t*0.5+1)*70, 190+Math.sin(t*0.55+3)*50, 0.1, 1.6, 0.85],
    [400+Math.sin(t*0.3+4)*80, 50+Math.cos(t*0.6+2)*60, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.28+5)*130, 210+Math.sin(t*0.42)*70, 0.075, 2.1, 0.95],
    [300+Math.sin(t*0.38+3)*90, 130+Math.cos(t*0.32+4)*80, 0.09, 1.8, 1.0],
    [160+Math.cos(t*0.45+2)*60, 40+Math.sin(t*0.5+5)*40, 0.11, 1.5, 0.8],
    [340+Math.sin(t*0.22+6)*100, 220+Math.cos(t*0.48+1)*50, 0.06, 2.4, 1.1]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+2.5)*w*0.4;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.2+Math.sin((sx-sy)*0.085-t*1.8)*0.2;
  const micro = (Math.sin(sx*0.12+sy*0.09+t*3)*Math.sin(sx*0.08-sy*0.11-t*2.5))*0.15;
  const bg = bg1+bg2+micro;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.5;
  const spiral = (sp1+sp2+sp3)/3;
  const rd = act - inh*0.65 + bg*0.25 + spiral*0.35 + cross*0.2;
  const feed = Math.sin(t*0.2)*0.1;
  const kill = Math.cos(t*0.15)*0.08;
  const reaction = Math.tanh((rd+feed)*2.0-kill);
  const cellA = Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB = Math.sin((sx+sy)*0.09+t*0.8)*Math.sin((sx-sy)*0.11-t*0.6);
  const cell = Math.tanh((cellA+cellB*0.6)*1.8)*0.25;
  const vein = Math.abs(Math.sin(sx*0.06+Math.sin(sy*0.04+t)*2)+Math.sin(sy*0.05+Math.cos(sx*0.03+t)*2))-0.8;
  const veinMask = Math.max(0, vein)*0.4;
  const blend = reaction*0.6+cell*0.2+veinMask*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [4,12,48],[8,32,82],[12,58,108],[18,88,128],
    [28,125,138],[55,158,132],[110,178,118],
    [175,190,85],[210,185,65],[225,165,72],
    [215,130,68],[195,90,62],[165,55,58],
    [120,32,52],[65,18,48],[30,10,44],[4,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.08:1.0;
  const glow = Math.max(0, 1.0-Math.abs(reaction)*1.5)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*90))|0
  ];
}
